Here's a single self-contained Python function that obtains the OS, architecture, and memory usage (total, used, and percent used). It uses psutil if available, and otherwise falls back to platform-specific built-ins (Unix sysconf or Windows ctypes). It returns a dictionary of the requested items.

```python
def get_system_details():
    """
    Return system details including operating system, architecture, and memory usage.

    Returned dict keys:
      - os: string (e.g. 'Linux 5.15.0-xx')
      - architecture: string (e.g. 'x86_64')
      - total_memory: int bytes or None
      - used_memory: int bytes or None
      - memory_used_percent: float percent (rounded to 2 decimals) or None
    """
    import platform
    import os
    from math import isfinite

    info = {
        "os": f"{platform.system()} {platform.release()}",
        "architecture": platform.machine() or platform.architecture()[0],
        "total_memory": None,
        "used_memory": None,
        "memory_used_percent": None,
    }

    # 1) Try using psutil if installed (simple and cross-platform)
    try:
        import psutil
        vm = psutil.virtual_memory()
        total = int(vm.total)
        used = int(vm.used)
        pct = float(vm.percent)
        info.update({
            "total_memory": total,
            "used_memory": used,
            "memory_used_percent": round(pct, 2)
        })
        return info
    except Exception:
        pass

    # 2) Windows: use GlobalMemoryStatusEx via ctypes
    try:
        if platform.system().lower().startswith("win"):
            import ctypes

            class MEMORYSTATUSEX(ctypes.Structure):
                _fields_ = [
                    ("dwLength", ctypes.c_ulong),
                    ("dwMemoryLoad", ctypes.c_ulong),
                    ("ullTotalPhys", ctypes.c_ulonglong),
                    ("ullAvailPhys", ctypes.c_ulonglong),
                    ("ullTotalPageFile", ctypes.c_ulonglong),
                    ("ullAvailPageFile", ctypes.c_ulonglong),
                    ("ullTotalVirtual", ctypes.c_ulonglong),
                    ("ullAvailVirtual", ctypes.c_ulonglong),
                    ("sullAvailExtendedVirtual", ctypes.c_ulonglong),
                ]

            stat = MEMORYSTATUSEX()
            stat.dwLength = ctypes.sizeof(MEMORYSTATUSEX)
            if ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(stat)):
                total = int(stat.ullTotalPhys)
                avail = int(stat.ullAvailPhys)
                used = total - avail
                pct = (used / total * 100.0) if total else None
                info.update({
                    "total_memory": total,
                    "used_memory": used,
                    "memory_used_percent": round(pct, 2) if pct is not None else None
                })
                return info
    except Exception:
        pass

    # 3) POSIX: try os.sysconf (works on Linux, macOS, many Unixes)
    try:
        if hasattr(os, "sysconf"):
            # page size
            page_size = None
            for name in ("SC_PAGE_SIZE", "SC_PAGESIZE"):
                try:
                    page_size = os.sysconf(name)
                    if isinstance(page_size, int):
                        break
                except (ValueError, OSError, TypeError):
                    page_size = None
            # total and available pages
            pages = None
            avail_pages = None
            try:
                pages = os.sysconf("SC_PHYS_PAGES")
            except Exception:
                pages = None
            try:
                avail_pages = os.sysconf("SC_AVPHYS_PAGES")
            except Exception:
                avail_pages = None

            if page_size and pages is not None:
                total = int(page_size) * int(pages)
                if avail_pages is not None:
                    avail = int(page_size) * int(avail_pages)
                    used = total - avail
                else:
                    # if avail not available, try reading /proc/meminfo (Linux)
                    used = None

                pct = (used / total * 100.0) if (used is not None and total) else None
                info.update({
                    "total_memory": total,
                    "used_memory": used if used is not None else None,
                    "memory_used_percent": round(pct, 2) if (pct is not None and isfinite(pct)) else None
                })
                if info["total_memory"] is not None:
                    return info
    except Exception:
        pass

    # 4) Fallback: parse /proc/meminfo (Linux)
    try:
        if os.path.exists("/proc/meminfo"):
            meminfo = {}
            with open("/proc/meminfo", "r") as f:
                for line in f:
                    parts = line.split(":")
                    if len(parts) < 2:
                        continue
                    key = parts[0].strip()
                    val = parts[1].strip().split()[0]
                    try:
                        meminfo[key] = int(val)  # usually kB
                    except Exception:
                        continue
            if "MemTotal" in meminfo:
                total = int(meminfo["MemTotal"]) * 1024
                # Prefer MemAvailable if present
                if "MemAvailable" in meminfo:
                    avail = int(meminfo["MemAvailable"]) * 1024
                elif "MemFree" in meminfo:
                    avail = int(meminfo["MemFree"]) * 1024
                else:
                    avail = None
                used = (total - avail) if (avail is not None) else None
                pct = (used / total * 100.0) if (used is not None and total) else None
                info.update({
                    "total_memory": total,
                    "used_memory": used,
                    "memory_used_percent": round(pct, 2) if pct is not None else None
                })
                return info
    except Exception:
        pass

    # If everything failed, return what we have (memory fields will be None)
    return info
```

Example usage:
```python
if __name__ == "__main__":
    details = get_system_details()
    print(details)
```

This function is designed to be robust: it tries psutil first (best cross-platform), then Windows API, then POSIX sysconf, then /proc/meminfo as a Linux fallback. Memory values are returned in bytes; percent is rounded to two decimals.

Here's a self-contained Python function that uses only the standard library to fetch a page and return the text content of the first occurrence of a given tag (e.g., "h1", "p", "title"). It handles nested tags inside the target tag and unescapes HTML entities.

```python
from html.parser import HTMLParser
import html as html_module
from urllib import request, error

class _FoundMarker(Exception):
    pass

class _FirstTagParser(HTMLParser):
    def __init__(self, target_tag):
        super().__init__(convert_charrefs=False)
        self.target = target_tag.lower()
        self.capturing = False
        self.capture_depth = 0
        self.chunks = []

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        if not self.capturing and tag == self.target:
            self.capturing = True
            self.capture_depth = 1
        elif self.capturing:
            self.capture_depth += 1

    def handle_endtag(self, tag):
        if self.capturing:
            self.capture_depth -= 1
            if self.capture_depth <= 0:
                # finished capturing first target tag
                raise _FoundMarker()

    def handle_data(self, data):
        if self.capturing:
            self.chunks.append(data)

    def handle_entityref(self, name):
        # keep entity text for later unescape
        if self.capturing:
            self.chunks.append(f"&{name};")

    def handle_charref(self, name):
        if self.capturing:
            self.chunks.append(f"&#{name};")

def get_first_tag_text(url, tag, timeout=10):
    """
    Fetches the page at `url`, finds the first occurrence of HTML tag `tag`
    (e.g. 'h1', 'p', 'title'), and returns its text content with HTML entities unescaped.
    Returns None if the tag isn't found or on network errors.

    Example:
        text = get_first_tag_text("https://example.com", "h1")
    """
    try:
        req = request.Request(url, headers={"User-Agent": "python-urllib/3"})
        with request.urlopen(req, timeout=timeout) as resp:
            # try to use declared charset, fallback to utf-8
            charset = resp.headers.get_content_charset() or "utf-8"
            raw = resp.read()
            html_text = raw.decode(charset, errors="replace")
    except (error.URLError, error.HTTPError, ValueError):
        return None

    parser = _FirstTagParser(tag)
    try:
        parser.feed(html_text)
        parser.close()
    except _FoundMarker:
        # expected early stop when the first tag is closed
        pass

    if not parser.chunks:
        return None

    text = html_module.unescape("".join(parser.chunks)).strip()
    return text if text != "" else ""
```

Notes:
- Returns None if the tag isn't found or on network errors. If the tag exists but has no text, returns an empty string.
- Uses only Python standard library modules (urllib and html.parser).

Here's a self-contained Python function that uses only the standard library (urllib and html.parser) to fetch a page and return the text content of the first occurrence of a specified HTML tag. It returns a string (stripped) or None if the tag isn't found.

```python
from html.parser import HTMLParser
from urllib.request import urlopen, Request
from urllib.error import URLError, HTTPError
import html

def fetch_first_tag_text(url, tag, timeout=10, headers=None):
    """
    Fetch the given URL and return the text content of the first occurrence
    of the specified HTML tag (case-insensitive). Returns None if not found.

    Args:
        url (str): URL of the page to fetch.
        tag (str): HTML tag name to search for (e.g. 'title', 'div', 'h1').
        timeout (int, optional): network timeout in seconds. Default 10.
        headers (dict, optional): extra headers for the request (e.g. {'User-Agent': '...'}).

    Returns:
        str or None: Text content of the first matching tag (whitespace trimmed),
                     or None if the tag does not occur.
    """
    class FirstTagTextParser(HTMLParser):
        def __init__(self, target_tag):
            super().__init__()
            self.target = target_tag.lower()
            self.found = False
            self.done = False
            self.depth = 0
            self.parts = []

        def handle_starttag(self, tag, attrs):
            if self.done:
                return
            tag_l = tag.lower()
            if tag_l == self.target:
                if not self.found:
                    self.found = True
                    self.depth = 1
                else:
                    # nested same tag inside the target
                    self.depth += 1

        def handle_endtag(self, tag):
            if self.done or not self.found:
                return
            tag_l = tag.lower()
            if tag_l == self.target:
                self.depth -= 1
                if self.depth <= 0:
                    self.done = True

        def handle_data(self, data):
            if self.found and not self.done:
                self.parts.append(data)

        def handle_entityref(self, name):
            if self.found and not self.done:
                # convert named entity like &amp; to '&'
                self.parts.append(html.unescape(f"&{name};"))

        def handle_charref(self, name):
            if self.found and not self.done:
                # numeric char ref (decimal or hex)
                self.parts.append(html.unescape(f"&#{name};"))

        def get_text(self):
            if not self.found:
                return None
            # join parts and unescape any remaining entities, then trim whitespace
            return html.unescape(''.join(self.parts)).strip()

    # Fetch the page
    req = Request(url, headers=headers or {'User-Agent': 'python-urllib/3'})
    try:
        with urlopen(req, timeout=timeout) as resp:
            raw = resp.read()
            # try to detect encoding from headers, fall back to utf-8
            encoding = None
            try:
                content_type = resp.headers.get_content_charset()
                if content_type:
                    encoding = content_type
            except Exception:
                encoding = None
            if not encoding:
                encoding = 'utf-8'
            text = raw.decode(encoding, errors='replace')
    except (HTTPError, URLError) as e:
        raise RuntimeError(f"Error fetching {url}: {e}") from e

    parser = FirstTagTextParser(tag)
    parser.feed(text)
    return parser.get_text()


# Example usage:
if __name__ == "__main__":
    url = "https://www.example.com"
    print(fetch_first_tag_text(url, "title"))   # prints the <title> text of example.com
```

Notes:
- Uses only Python standard library (no external dependencies).
- The parser collects text inside the first matching tag, including text inside nested elements, and decodes HTML entities.
- Returns None if the tag doesn't appear. Errors fetching the URL raise a RuntimeError with details.

Here's a self-contained Python function that uses only the standard library. It fetches a web page and returns the text content of the first occurrence of a specified HTML tag (e.g., "div", "p", "h1"). If the tag is not present it returns None.

```python
from html.parser import HTMLParser
from html import unescape
from html.entities import name2codepoint
from urllib.request import Request, urlopen
from urllib.error import URLError, HTTPError

class _StopParsing(Exception):
    """Internal exception used to stop HTMLParser early."""
    pass

class _FirstTagTextParser(HTMLParser):
    def __init__(self, target_tag):
        super().__init__()
        self.target = target_tag.lower()
        self.depth = 0            # depth inside occurrences of target tag
        self.found = False        # found at least one target start tag
        self.chunks = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() == self.target:
            # entering a target tag (maybe nested)
            if self.depth == 0:
                self.found = True
            self.depth += 1

    def handle_endtag(self, tag):
        if tag.lower() == self.target and self.depth > 0:
            self.depth -= 1
            if self.depth == 0 and self.found:
                # we've closed the first occurrence; stop parsing early
                raise _StopParsing()

    def handle_data(self, data):
        if self.depth > 0:
            self.chunks.append(data)

    def handle_entityref(self, name):
        if self.depth > 0:
            # convert named entity to character if possible
            try:
                self.chunks.append(chr(name2codepoint[name]))
            except KeyError:
                self.chunks.append("&" + name + ";")

    def handle_charref(self, name):
        if self.depth > 0:
            try:
                if name.startswith(("x", "X")):
                    codepoint = int(name[1:], 16)
                else:
                    codepoint = int(name)
                self.chunks.append(chr(codepoint))
            except Exception:
                self.chunks.append("&#" + name + ";")

def scrape_first_tag_text(url, tag, timeout=10):
    """
    Fetch the URL and return the text content of the first occurrence of the specified HTML tag.
    - url: string, the page URL
    - tag: string, tag name like 'div', 'p', 'h1' (case-insensitive)
    - timeout: socket timeout in seconds for the HTTP request

    Returns the inner text (str) or None if the tag was not found.
    Raises URLError/HTTPError on network problems, ValueError for invalid input.
    """
    if not tag or not isinstance(tag, str):
        raise ValueError("tag must be a non-empty string")

    req = Request(url, headers={"User-Agent": "Mozilla/5.0 (compatible)"})
    try:
        with urlopen(req, timeout=timeout) as resp:
            # attempt to get charset from headers, fallback to utf-8
            charset = None
            headers = getattr(resp, "headers", None)
            if headers and hasattr(headers, "get_content_charset"):
                charset = headers.get_content_charset()
            if not charset:
                # try the older .info() method (fallback)
                try:
                    info = resp.info()
                    if hasattr(info, "get_content_charset"):
                        charset = info.get_content_charset()
                except Exception:
                    charset = None
            if not charset:
                charset = "utf-8"
            html_bytes = resp.read()
            html_text = html_bytes.decode(charset, errors="replace")
    except (HTTPError, URLError):
        # propagate network errors
        raise
    except Exception as exc:
        raise RuntimeError("Failed to fetch or decode the URL: " + str(exc))

    parser = _FirstTagTextParser(tag)
    try:
        parser.feed(html_text)
        parser.close()
    except _StopParsing:
        # expected way to stop early once first target tag closed
        pass

    if not parser.found:
        return None

    result = "".join(parser.chunks)
    # normalize/convert any remaining entities and trim
    return unescape(result).strip()

# Example usage:
# text = scrape_first_tag_text("https://www.example.com", "h1")
# print(text)
```

Notes:
- Uses only the Python standard library (urllib + html.parser).
- Handles nested tags inside the matched tag and converts HTML entities.
- Returns None if the requested tag isn't found. Network errors are raised to the caller.

def product_of_seconds(tuples):
    """
    Calculate the product of the second values in each tuple in a list (or tuple) of tuples
    and return the product as a single-element NumPy array.

    - If the input list is empty, the product returned is 1 (multiplicative identity).
    - Raises TypeError if input is not a list/tuple and ValueError if any item lacks a second element.
    """
    import numpy as np

    if not isinstance(tuples, (list, tuple)):
        raise TypeError("Input must be a list or tuple of tuples/sequences.")

    seconds = []
    for i, item in enumerate(tuples):
        try:
            seconds.append(item[1])
        except Exception:
            raise ValueError(f"Item at index {i} does not have a second element: {item}")

    prod = np.prod(seconds)  # np.prod([]) -> 1.0
    return np.array([prod])

# Example:
# product_of_seconds([(1, 2), (3, 4), (5, 6)]) -> array([48])

