def geolocate_host(host: str, timeout: float = 5.0) -> Dict[str, Any]:
    """
    Resolve the IP address of `host` and fetch geolocation information from ipinfo.io.
    Returns a dictionary with keys:
      - success (bool)
      - ip (str | None): resolved IP address (if resolution succeeded)
      - data (dict | None): parsed JSON response from ipinfo.io when successful
      - error (str | None): human-readable error message on failure
      - status_code (int | None): HTTP status code returned by ipinfo.io (when available)
      - raw (str | None): raw response body when JSON parsing fails (optional)
      - body (str | None): body of error responses (optional)

    The function is implemented using only the Python standard library and handles common
    errors such as invalid hostnames, network issues, timeouts, HTTP errors, and JSON errors.

    Example:
      result = geolocate_host("example.com", timeout=4.0)
      if result["success"]:
          print("IP:", result["ip"])
          print("Geo data:", result["data"])
      else:
          print("Error:", result["error"])
    """
    if not isinstance(host, str) or not host:
        return {"success": False, "ip": None, "data": None, "error": "host must be a non-empty string", "status_code": None}

    # Resolve host -> get an IP address (prefer IPv4, fallback to IPv6)
    try:
        addrs = socket.getaddrinfo(host, None)
    except socket.gaierror as e:
        return {"success": False, "ip": None, "data": None, "error": f"DNS resolution failed: {e}", "status_code": None}
    except Exception as e:
        return {"success": False, "ip": None, "data": None, "error": f"Unexpected error during DNS resolution: {e}", "status_code": None}

    ip: Optional[str] = None
    for family, _, _, _, sockaddr in addrs:
        if family == socket.AF_INET:  # IPv4
            ip = sockaddr[0]
            break
    if ip is None:
        for family, _, _, _, sockaddr in addrs:
            if family == socket.AF_INET6:  # IPv6
                ip = sockaddr[0]
                break
    if ip is None:
        return {"success": False, "ip": None, "data": None, "error": "No IPv4/IPv6 address found for host", "status_code": None}

    # Query ipinfo.io for the resolved IP
    url = f"https://ipinfo.io/{ip}/json"
    req = urllib.request.Request(url, headers={"User-Agent": "python-urllib/3"})

    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            status = getattr(resp, "getcode", lambda: None)()
            raw = resp.read().decode("utf-8", errors="replace")
            try:
                data = json.loads(raw)
            except json.JSONDecodeError:
                return {"success": False, "ip": ip, "data": None, "error": "Invalid JSON received from ipinfo.io", "raw": raw, "status_code": status}
            return {"success": True, "ip": ip, "data": data, "error": None, "status_code": status}
    except urllib.error.HTTPError as e:
        # HTTPError is also a file-like object; try to read body
        try:
            body = e.read().decode("utf-8", errors="replace")
        except Exception:
            body = None
        return {"success": False, "ip": ip, "data": None, "error": f"HTTP error fetching geolocation: {e.code} {e.reason}", "status_code": e.code, "body": body}
    except urllib.error.URLError as e:
        # Could be a timeout, connection refused, DNS error for ipinfo.io, etc.
        reason = getattr(e, "reason", str(e))
        return {"success": False, "ip": ip, "data": None, "error": f"Network error fetching geolocation: {reason}", "status_code": None}
    except socket.timeout:
        return {"success": False, "ip": ip, "data": None, "error": "Request to ipinfo.io timed out", "status_code": None}
