import urllib.error
import urllib.parse
from typing import Optional, Dict, Any


def get_geolocation_for_host(host: str, timeout: float = 5.0) -> Dict[str, Any]:
    """
    Resolve the given host to an IP address and fetch geolocation info from ipinfo.io.

    Returns a dictionary with the following keys:
      - ok (bool): whether the operation succeeded
      - ip (str|None): resolved IP address (if any)
      - geo (dict|None): parsed JSON geolocation info from ipinfo.io (if ok)
      - error (str|None): human-readable error message (if not ok)

    The function is robust against:
      - invalid hostnames (DNS resolution errors)
      - network problems (timeouts, connection errors)
      - HTTP errors from the geolocation service
      - invalid/non-JSON responses

    Example:
      >>> result = get_geolocation_for_host("example.com")
      >>> if result["ok"]:
      ...     print(result["ip"], result["geo"])
      ... else:
      ...     print("Error:", result["error"])

    Parameters:
      host: hostname or IP string to resolve
      timeout: socket/HTTP timeout in seconds (float)

    Notes:
      - Uses only Python standard library (socket and urllib).
      - No external API key is required for basic ipinfo.io fields (rate-limited).
    """
    if not host or not isinstance(host, str):
        return {"ok": False, "ip": None, "geo": None, "error": "host must be a non-empty string"}

    ip = None

    # 1) Resolve hostname to an IP address (prefer IPv4 but accept IPv6)
    try:
        addrinfo = socket.getaddrinfo(host, None)
        # prefer IPv4 (AF_INET) if available
        ip = None
        for family, _, _, _, sockaddr in addrinfo:
            candidate = sockaddr[0]
            if family == socket.AF_INET:
                ip = candidate
                break
            if ip is None:
                ip = candidate
    except socket.gaierror as e:
        return {"ok": False, "ip": None, "geo": None, "error": f"DNS resolution failed: {e}"}
    except Exception as e:
        return {"ok": False, "ip": None, "geo": None, "error": f"Unexpected error during DNS resolution: {e}"}

    if not ip:
        return {"ok": False, "ip": None, "geo": None, "error": "No IP address found for host"}

    # 2) Query ipinfo.io for geolocation info
    # Quote the IP for safe inclusion in the URL (allow colons for IPv6)
    quoted_ip = urllib.parse.quote(ip, safe=":")

    url = f"https://ipinfo.io/{quoted_ip}/json"
