```python
import random

def vegetable_stats(people_prefs, seed=None):
    """
    Calculate statistics for vegetables preferred by people.

    Args:
        people_prefs (dict): mapping person -> vegetable (string)
        seed (int, optional): seed for random to make results deterministic

    Returns:
        dict: {
            'veg_to_people': dict mapping vegetable -> list of people who prefer it,
            'veg_to_person': dict mapping vegetable -> single person (chosen from veg_to_people),
            'counts': dict mapping vegetable -> random int count (1..10),
            'percentages': dict mapping vegetable -> percentage of total counts (rounded to 2 decimals)
        }

    Example:
        prefs = {'Alice': 'carrot', 'Bob': 'peas', 'Carol': 'carrot'}
        stats = vegetable_stats(prefs, seed=42)
    """
    if seed is not None:
        random.seed(seed)

    # Reverse mapping: vegetable -> list of people who like it
    veg_to_people = {}
    for person, veg in people_prefs.items():
        veg_to_people.setdefault(veg, []).append(person)

    # If no vegetables (empty input), return empty results
    if not veg_to_people:
        return {
            'veg_to_people': {},
            'veg_to_person': {},
            'counts': {},
            'percentages': {}
        }

    # Map each vegetable to a single person (choose randomly if multiple)
    veg_to_person = {veg: random.choice(people) for veg, people in veg_to_people.items()}

    # Assign random counts between 1 and 10 to each vegetable
    counts = {veg: random.randint(1, 10) for veg in veg_to_people.keys()}

    # Calculate percentages of total counts
    total = sum(counts.values())
    percentages = {}
    if total > 0:
        for veg, cnt in counts.items():
            percentages[veg] = round((cnt / total) * 100, 2)
    else:
        percentages = {veg: 0.0 for veg in counts.keys()}

    return {
        'veg_to_people': veg_to_people,
        'veg_to_person': veg_to_person,
        'counts': counts,
        'percentages': percentages
    }

# Example usage
