Here's a self-contained Python function that uses only the standard library. It samples the number of customers from a Poisson distribution (Knuth's algorithm), has each customer buy exactly one randomly chosen animal from the provided list, prints a readable summary, and returns the results as a dictionary.

```python
import math
import random
from typing import List, Dict, Any

def simulate_pet_shop_sales(animals: List[str], mu: float, seed: int = None) -> Dict[str, Any]:
    """
    Simulate sales in a pet shop.

    - animals: list of animal types (non-empty).
    - mu: mean of the Poisson distribution for number of customers (mu >= 0).
    - seed: optional random seed for reproducibility.

    Returns a dictionary:
      {
        'customers': N,
        'sales': {animal: count, ...}
      }

    Also prints a summary to stdout.
    """
    if not animals:
        raise ValueError("animals list must be non-empty")
    if mu < 0:
        raise ValueError("mu must be non-negative")

    if seed is not None:
        random.seed(seed)

    # Sample Poisson using Knuth's algorithm
    if mu == 0:
        num_customers = 0
    else:
        L = math.exp(-mu)
        k = 0
        p = 1.0
        while p > L:
            k += 1
            p *= random.random()
        num_customers = k - 1

    # Initialize counts
    counts = {animal: 0 for animal in animals}

    # Each customer buys one random animal
    for _ in range(num_customers):
        choice = random.choice(animals)
        counts[choice] += 1

    # Print summary
    print(f"Simulated customers: {num_customers}")
    if num_customers == 0:
        for animal in animals:
            print(f"  {animal}: 0 (0.0%)")
    else:
        for animal in animals:
            cnt = counts[animal]
            pct = 100.0 * cnt / num_customers
            print(f"  {animal}: {cnt} ({pct:.1f}%)")

    return {'customers': num_customers, 'sales': counts}

# Example usage:
# simulate_pet_shop_sales(['dog', 'cat', 'parrot'], mu=5.0, seed=42)
```

