def most_common_words_in_json_dir(
    directory: str,
    top_n: int = 10,
    key: Optional[str] = None,
    include_subdirs: bool = False,
    min_length: int = 1,
    exclude: Optional[Iterable[str]] = None,
    lowercase: bool = True
) -> List[Tuple[str, int]]:
    """
    Scan all .json files in `directory` (optionally including subdirectories),
    extract textual content from each JSON file, and return the `top_n` most
    common words with counts.

    Parameters:
    - directory: path to folder containing JSON files.
    - top_n: number of most common words to return.
    - key: optional dot-separated key path (e.g. "article.body") to extract text from a specific field.
           If None, all string values anywhere in the JSON are extracted.
    - include_subdirs: if True, search JSON files recursively in subdirectories.
    - min_length: ignore tokens shorter than this length.
    - exclude: iterable of words to exclude (e.g. stopwords). Comparison respects `lowercase`.
    - lowercase: convert tokens to lowercase before counting.

    Returns:
    - List of (word, count) tuples sorted by frequency (most common first).

    Example:
    >>> most_common_words_in_json_dir("data/jsons", top_n=20, key="text")
    """
    # compile tokenizer: words (alphanumeric + underscore)
    token_re = re.compile(r"\b\w+\b", flags=re.UNICODE)
    exclude_set: Set[str] = set(w.lower() for w in exclude) if exclude else set()

    def iter_json_strings(obj):
        """Yield all string values in a JSON-loaded object (recursively)."""
        if isinstance(obj, str):
            yield obj
        elif isinstance(obj, dict):
            for v in obj.values():
                yield from iter_json_strings(v)
        elif isinstance(obj, list) or isinstance(obj, tuple):
            for item in obj:
                yield from iter_json_strings(item)
        # other JSON types (int/float/bool/None) are ignored

    def get_by_key_path(obj, path: str):
        """Get value from obj following dot-separated path; return None if any key missing."""
        cur = obj
        for part in path.split("."):
            if isinstance(cur, dict) and part in cur:
                cur = cur[part]
            else:
                return None
        return cur

    # gather files
    files = []
    if include_subdirs:
        for root, _, filenames in os.walk(directory):
            for fn in filenames:
                if fn.lower().endswith(".json"):
                    files.append(os.path.join(root, fn))
    else:
        for fn in os.listdir(directory):
            if fn.lower().endswith(".json"):
                files.append(os.path.join(directory, fn))

    counter = Counter()
    for filepath in files:
        try:
            with open(filepath, "r", encoding="utf-8") as f:
                data = json.load(f)
        except Exception:
            # skip files that cannot be read/parsed
            continue

        if key:
            val = get_by_key_path(data, key)
            if val is None:
                # nothing at that key, skip file
                continue
            strings_iter = iter_json_strings(val)
        else:
            strings_iter = iter_json_strings(data)

        for text in strings_iter:
            if lowercase:
                text = text.lower()
            for token in token_re.findall(text):
                if len(token) < min_length:
                    continue
                if lowercase:
                    check_token = token
                else:
                    check_token = token.lower()
                if check_token in exclude_set:
                    continue
                counter[token if not lowercase else check_token] += 1

    return counter.most_common(top_n)
