import math
from typing import Any, Dict, Iterable, List, Union

def analyze_stock_column(rows: Iterable[Union[dict, list, tuple]], column: Union[str, int]) -> Dict[str, float]:
    """
    Analyze numeric values for a specified column in stock data.

    Parameters:
    - rows: iterable of records. Each record can be a dict (preferred) or a sequence (list/tuple).
    - column: key name (str) when rows are dicts, or index (int) when rows are sequences.

    Returns:
    A dict with keys: 'sum', 'mean', 'min', 'max', 'count' (all floats except count as int).
    Raises ValueError if no numeric values are found for the given column.

    Example:
    rows = [
        {'date': '2020-01-01', 'close': '100.5'},
        {'date': '2020-01-02', 'close': 101.25},
        {'date': '2020-01-03', 'close': None},  # ignored
    ]
    analyze_stock_column(rows, 'close')
    """
    values: List[float] = []

    for row in rows:
        # Extract value by key (dict) or by index (sequence)
        try:
            if isinstance(row, dict):
                val = row.get(column)
            else:
                # assume sequence; column must be int
                if not isinstance(column, int):
                    val = None
                else:
                    # handle short sequences gracefully
                    try:
                        val = row[column]
                    except Exception:
                        val = None
        except Exception:
            val = None

        # Normalize and convert to float if possible
        if val is None:
            continue
        if isinstance(val, str):
            text = val.strip()
            if text == '':
                continue
            # remove common thousands separators
            text = text.replace(',', '')
            try:
                num = float(text)
            except ValueError:
                continue
        else:
            try:
                num = float(val)
            except (TypeError, ValueError):
                continue

        # ignore NaN or infinite values
        if math.isnan(num) or math.isinf(num):
            continue

        values.append(num)

    if not values:
        raise ValueError(f"No valid numeric values found for column {column!r}")

    total = sum(values)
    count = len(values)
    minimum = min(values)
    maximum = max(values)
    mean = total / count

    return {'sum': total, 'mean': mean, 'min': minimum, 'max': maximum, 'count': count}

