def summarize_column(data: Iterable, column: Any, *, ignore_missing: bool = True) -> Dict[str, Optional[float]]:
    """
    Summarize numeric values for a specified column in stock data.

    Parameters:
    - data: iterable of rows, where each row is either a dict (use a string/key) or a sequence (use an int index).
    - column: key (for dict rows) or index (for sequence rows) identifying the column to summarize.
    - ignore_missing: if True, skip rows where the column is missing or not a valid number;
                      if False, raise an error on missing/non-numeric values.

    Returns:
    A dict with keys: 'count', 'sum', 'mean', 'min', 'max'.
    If no valid numeric values are found, 'count' is 0 and others are None.

    Example usage:
    data_dicts = [
        {'date': '2025-01-01', 'close': 101.5, 'volume': 1000},
        {'date': '2025-01-02', 'close': 102.0, 'volume': 1100},
        {'date': '2025-01-03', 'close': None, 'volume': 900},
    ]
    summarize_column(data_dicts, 'close')
    # -> {'count': 2, 'sum': 203.5, 'mean': 101.75, 'min': 101.5, 'max': 102.0}

    data_seqs = [
        ('2025-01-01', 101.5, 1000),
        ('2025-01-02', 102.0, 1100),
    ]
    summarize_column(data_seqs, 1)  # summarize by index 1 (close price)
    """
    values: List[float] = []

    for i, row in enumerate(data):
        # extract value based on row type
        try:
            if isinstance(row, dict):
                if column not in row:
                    if ignore_missing:
                        continue
                    raise KeyError(f"Missing key {column} in row {i}")
                raw = row[column]
            else:
                # treat as sequence
                try:
                    raw = row[column]
                except Exception:
                    if ignore_missing:
                        continue
                    raise IndexError(f"Cannot access index {column} in row {i}")
        except Exception:
            # propagate unexpected extraction errors
            raise

        # skip None/empty string
        if raw is None or raw == '':
            if ignore_missing:
                continue
            raise ValueError(f"Non-numeric value at row {i}: {raw!r}")

        # try convert to float
        try:
            num = float(raw)
        except Exception:
            if ignore_missing:
                continue
            raise ValueError(f"Non-numeric value at row {i}: {raw!r}")

        # skip NaN or infinities
        if math.isnan(num) or math.isinf(num):
            if ignore_missing:
                continue
            raise ValueError(f"Non-finite numeric value at row {i}: {raw!r}")

        values.append(num)

    if not values:
        return {'count': 0, 'sum': None, 'mean': None, 'min': None, 'max': None}

    total = sum(values)
    cnt = len(values)
    return {
        'count': cnt,
        'sum': total,
        'mean': total / cnt,
        'min': min(values),
        'max': max(values),
    }
