import json
import urllib.request
import urllib.error
import unicodedata
from typing import Any, Dict

def get_github_user_ascii(username: str) -> Dict[str, Any]:
    """
    Retrieve GitHub user information for `username`, normalize all string data to ASCII,
    and return a dictionary of the normalized data.

    - Uses only Python standard library (urllib).
    - Normalizes both keys and string values (recursively) using Unicode NFKD and
      ASCII transliteration (drops characters that can't be converted to ASCII).
    - Raises ValueError on HTTP errors or if returned data is not a JSON object.

    Example:
        info = get_github_user_ascii("octocat")
    """
    if not isinstance(username, str) or not username:
        raise ValueError("username must be a non-empty string")

    url = f"https://api.github.com/users/{urllib.parse.quote(username)}"
    req = urllib.request.Request(url, headers={"User-Agent": "python-urllib/3"})

    try:
        with urllib.request.urlopen(req) as resp:
            # Read and parse JSON
            data = json.load(resp)
    except urllib.error.HTTPError as e:
        # Try to read message from GitHub error body
        try:
            err_body = e.read().decode("utf-8", errors="ignore")
            err_json = json.loads(err_body)
            message = err_json.get("message", err_body)
        except Exception:
            message = str(e)
        raise ValueError(f"GitHub API error: {message}") from e
    except urllib.error.URLError as e:
        raise ValueError(f"Network error: {e.reason}") from e

    if not isinstance(data, dict):
        raise ValueError("Expected a JSON object from GitHub API")

    def to_ascii(s: str) -> str:
        # Normalize to NFKD, then drop non-ASCII bytes
        return unicodedata.normalize("NFKD", s).encode("ascii", "ignore").decode("ascii")

    def normalize(obj: Any) -> Any:
        if isinstance(obj, str):
            return to_ascii(obj)
        if isinstance(obj, bytes):
            try:
                return to_ascii(obj.decode("utf-8"))
            except Exception:
                return obj  # leave as-is if decoding fails
        if isinstance(obj, dict):
            new = {}
            for k, v in obj.items():
                new_key = to_ascii(k) if isinstance(k, str) else k
                new[new_key] = normalize(v)
            return new
        if isinstance(obj, list):
            return [normalize(item) for item in obj]
        if isinstance(obj, tuple):
            return tuple(normalize(item) for item in obj)
        return obj  # numbers, booleans, None, etc.

    return normalize(data)
