Here's a simple, self-contained Python function that reads a CSV, converts a column of date strings into datetime objects, extracts the years, and draws a histogram of the year distribution. It uses only the standard csv and datetime modules plus matplotlib for plotting. If you have python-dateutil installed, the function will use it to parse a wide range of date formats automatically; otherwise you can pass a strptime-style date_format.

```python
import csv
from datetime import datetime
import matplotlib.pyplot as plt

def plot_year_histogram(csv_path, date_column, date_format=None, delimiter=',',
                        has_header=True, title=None, figsize=(8,4), show=True):
    """
    Read a CSV file, parse a column of date strings into datetimes, and plot a histogram
    of the year distribution.

    Parameters:
    - csv_path: path to CSV file
    - date_column: column name (if has_header=True) or column index (int) if has_header=False
    - date_format: optional strptime format (e.g. '%Y-%m-%d'). If None, the function will:
        1) try datetime.fromisoformat,
        2) then try dateutil.parser.parse if python-dateutil is installed,
        3) then try a few common formats as a fallback.
    - delimiter: CSV delimiter (default ',')
    - has_header: whether the CSV has a header row (default True)
    - title: optional plot title
    - figsize: tuple for figure size
    - show: if True (default), call plt.show(); otherwise the caller can save or manipulate the figure

    Returns: None
    """
    # helper: try to parse a single date string
    def parse_date(s):
        s = s.strip()
        if not s:
            return None
        if date_format:
            try:
                return datetime.strptime(s, date_format)
            except Exception:
                return None
        # try ISO
        try:
            return datetime.fromisoformat(s)
        except Exception:
            pass
        # try dateutil if available
        try:
            from dateutil import parser as du_parser
            return du_parser.parse(s)
        except Exception:
            pass
        # fallback common formats
        common_formats = [
            '%Y-%m-%d', '%d/%m/%Y', '%m/%d/%Y', '%Y/%m/%d',
            '%d-%m-%Y', '%m-%d-%Y', '%b %d %Y', '%B %d %Y',
            '%d %b %Y', '%d %B %Y'
        ]
        for fmt in common_formats:
            try:
                return datetime.strptime(s, fmt)
            except Exception:
                continue
        return None

    years = []
    with open(csv_path, newline='', encoding='utf-8') as f:
        if has_header:
            reader = csv.DictReader(f, delimiter=delimiter)
            for row in reader:
                try:
                    date_str = row[date_column]
                except KeyError:
                    raise KeyError(f"Column name '{date_column}' not found in CSV header.")
                dt = parse_date(date_str)
                if dt:
                    years.append(dt.year)
        else:
            reader = csv.reader(f, delimiter=delimiter)
            for row in reader:
                try:
                    date_str = row[date_column]
                except Exception:
                    raise IndexError(f"Column index {date_column} out of range for row: {row}")
                dt = parse_date(date_str)
                if dt:
                    years.append(dt.year)

    if not years:
        raise ValueError("No valid dates found in the specified column.")

    min_year, max_year = min(years), max(years)
    # Create integer bins so each year is one bin
    bins = list(range(min_year, max_year + 2))  # +2 so the last year has a right edge

    plt.figure(figsize=figsize)
    plt.hist(years, bins=bins, align='left', edgecolor='black')
    plt.xticks(bins[:-1], rotation=45)
    plt.xlabel('Year')
    plt.ylabel('Count')
    if title:
        plt.title(title)
    else:
        plt.title(f'Year distribution ({min_year}–{max_year})')
    plt.tight_layout()
    if show:
        plt.show()
```

Example usage:
- CSV with header: a column named "date":
  plot_year_histogram("data.csv", "date")
- CSV without header and date in the 2nd column (index 1), using a known format:
  plot_year_histogram("data_no_header.csv", 1, date_format="%m/%d/%Y", has_header=False)

Notes:
- Requires matplotlib (pip install matplotlib).
- If your dates use many different formats, install python-dateutil (pip install python-dateutil) for robust parsing.

Here's a self-contained Python function that (1) lowercases and tokenizes a sentence, (2) stems every word except the last one using a small rule-based stemmer (no external libraries required), and (3) returns a dictionary of stem -> frequency. The last word is left unstemmed but is included in the counts as-is (you can change this behavior if you prefer to exclude the last word entirely).

```python
def stem_and_count(sentence):
    """
    Stem every word in `sentence` except the last word, and count frequencies of each stem.
    Uses a simple rule-based stemmer (no external libraries).
    Returns a dict: {stem: count}.

    Behavior:
    - Case-insensitive (everything lowercased).
    - Tokenizes on word boundaries (letters, digits, underscore).
    - The last token is NOT stemmed but is counted in its original (lowercased) form.
    - Short words (<= 3 chars) are generally left unchanged.

    Example:
      stem_and_count("Running runners ran quickly to the houses")
      -> {'run': 2, 'ran': 1, 'quick': 1, 'to': 1, 'the': 1, 'houses': 1}
      (Note: 'houses' is the last token and left unstemmed.)
    """
    import re
    from collections import Counter

    # simple rule-based stemmer (not a full Porter stemmer)
    def _simple_stem(w):
        if len(w) <= 3:
            return w
        # common special case: 'ies' -> 'y' (e.g., 'parties' -> 'party')
        if w.endswith('ies') and len(w) > 4:
            return w[:-3] + 'y'
        # remove common suffixes when reasonable
        for suf in ('ation', 'ing', 'edly', 'edly', 'edly', 'edly', 'edly'):
            pass  # keep this line to allow next block to handle suffixes explicitly

        if w.endswith('ing') and len(w) - 3 >= 3:
            return w[:-3]
        if w.endswith('edly') and len(w) - 4 >= 3:
            return w[:-4]
        if w.endswith('ed') and len(w) - 2 >= 3:
            return w[:-2]
        if w.endswith('ly') and len(w) - 2 >= 3:
            return w[:-2]
        if w.endswith('es') and len(w) - 2 >= 3:
            return w[:-2]
        if w.endswith('s') and len(w) - 1 >= 3:
            return w[:-1]
        for suf in ('ment', 'ness', 'able', 'ible', 'ful', 'less', 'ation'):
            if w.endswith(suf) and len(w) - len(suf) >= 3:
                return w[:-len(suf)]
        return w

    # tokenize: words comprised of letters/digits/underscore
    tokens = re.findall(r"\b\w+\b", (sentence or "").lower())
    if not tokens:
        return {}

    counts = Counter()
    last_index = len(tokens) - 1

    for i, tok in enumerate(tokens):
        if i == last_index:
            # do not stem the last token; count it in its original lowercased form
            stem = tok
        else:
            stem = _simple_stem(tok)
        counts[stem] += 1

    return dict(counts)
```

