def nested_median(L):
    """
    Compute the median of all numeric elements in a nested list L.
    Raises ValueError if no numeric elements found, TypeError for non-numeric leaf items.
    """
    flat = []
    def _flatten(seq):
        for item in seq:
            if isinstance(item, list):
                _flatten(item)
            else:
                if isinstance(item, (int, float)):
                    flat.append(item)
                else:
                    # try converting strings like "3.5" to float, but reject other types
                    try:
                        flat.append(float(item))
                    except Exception:
                        raise TypeError(f"Non-numeric element encountered: {item!r}")
    _flatten(L)
    if not flat:
        raise ValueError("No numeric elements in the nested list.")
    flat.sort()
    n = len(flat)
    mid = n // 2
    if n % 2 == 1:
        return flat[mid]
    else:
        return (flat[mid - 1] + flat[mid]) / 2

