import numbers

def nested_median(L):
    """
    Calculate the median of all numeric elements in a nested list/tuple L.
    Supports arbitrary nesting of lists/tuples. Raises ValueError if no numeric
    elements are found and TypeError if a non-numeric, non-list/tuple element is encountered.

    Example:
      nested_median([1, [2, 3], [[4], 5]])  -> 3
      nested_median([1, 2, [3, 4]])         -> 2.5
    """
    def _flatten(x):
        for item in x:
            if isinstance(item, (list, tuple)):
                yield from _flatten(item)
            else:
                if not isinstance(item, numbers.Number):
                    raise TypeError(f"Non-numeric element encountered: {item!r}")
                yield item

    flat = list(_flatten(L))
    if not flat:
        raise ValueError("No numeric elements in the nested list")

    flat.sort()
    n = len(flat)
    mid = n // 2
    if n % 2 == 1:
        return flat[mid]
    else:
        return (flat[mid - 1] + flat[mid]) / 2
