Here's a simple self-contained Python function that flattens a nested list (lists/tuples), computes quartiles using the common "median of lower/upper halves" convention, and returns the interquartile range (Q3 - Q1). It uses only built-ins and converts items to float.

```python
def iqr(L):
    """
    Compute the interquartile range (IQR) of all numeric elements in a nested list/tuple L.
    Uses the common convention: for odd n exclude the median from halves; for even n split evenly.
    Returns a float (Q3 - Q1).
    Raises ValueError if no numeric data is found, TypeError if non-numeric items are present.
    """
    # Flatten nested lists/tuples
    flat = []
    def _flatten(x):
        if isinstance(x, (list, tuple)):
            for item in x:
                _flatten(item)
        else:
            flat.append(x)
    _flatten(L)

    # Convert to floats and validate
    nums = []
    for v in flat:
        try:
            nums.append(float(v))
        except Exception:
            raise TypeError(f"Non-numeric value encountered: {v!r}")

    n = len(nums)
    if n == 0:
        raise ValueError("No numeric data to compute IQR.")
    if n == 1:
        return 0.0

    nums.sort()

    def median(arr):
        m = len(arr)
        if m == 0:
            # Shouldn't happen for n>=2 with our splitting below
            raise ValueError("Cannot compute median of empty list.")
        mid = m // 2
        if m % 2 == 1:
            return float(arr[mid])
        else:
            return (arr[mid - 1] + arr[mid]) / 2.0

    # Split into lower and upper halves
    mid = n // 2
    if n % 2 == 0:
        lower = nums[:mid]
        upper = nums[mid:]
    else:
        lower = nums[:mid]         # excludes the median
        upper = nums[mid + 1:]     # excludes the median

    q1 = median(lower)
    q3 = median(upper)
    return float(q3 - q1)

# Example:
# print(iqr([[1,2,3],[4,5],[6]]))  # -> 3.0 (Q1=2, Q3=5)
```

