import csv
from collections import defaultdict

def most_common_values_in_csv(file_path):
    if not file_path:
        return {}

    column_data = defaultdict(list)

    with open(file_path, mode='r', newline='') as csvfile:
        reader = csv.DictReader(csvfile)
        if not reader.fieldnames:
            return {}

        for row in reader:
            for column, value in row.items():
                column_data[column].append(value)

    most_common_values = {}

    for column, values in column_data.items():
        value_counts = {}
        for value in values:
            if value in value_counts:
                value_counts[value] += 1
            else:
                value_counts[value] = 1

        # Find the most common value, with alphabetical tie-breaking
        most_common = min(value_counts.items(), key=lambda x: (-x[1], x[0]))[0]
        most_common_values[column] = most_common

    return most_common_values

