```python
import csv
from collections import Counter

def most_common_in_csv(path):
    """
    Return a dict mapping each column name in the CSV at `path` to its most common value.
    - Uses the CSV header row as column names.
    - If several values tie for most common, the alphabetically first value is chosen.
    - If the file is empty (no header), returns an empty dict.
    - If a column has no observed values (header present but no data rows), the value returned for that column is '' (empty string).
    """
    with open(path, newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        # If the CSV has no header (empty file), fieldnames is None
        if reader.fieldnames is None:
            return {}
        # Prepare counters for each column
        counters = {name: Counter() for name in reader.fieldnames}
        for row in reader:
            for name in reader.fieldnames:
                val = row.get(name)
                # Convert None (missing field) to empty string
                if val is None:
                    val = ''
                counters[name][val] += 1

    result = {}
    for name, counter in counters.items():
        if not counter:
            # Header present but no data rows: return empty string for that column
            result[name] = ''
        else:
            max_count = max(counter.values())
            # collect values tied for max_count and choose alphabetically first
            candidates = [v for v, c in counter.items() if c == max_count]
            result[name] = min(candidates)
    return result
