    """
    # Normalize path to list of components
    if isinstance(path, str):
        comps = [p for p in path.split('.') if p != '']
    else:
        comps = list(path)

    # Start with the root object
    current = [json_obj]

    for comp in comps:
        next_level = []
        for node in current:
            if comp == '*':
                # Expand all items/values
                if isinstance(node, dict):
                    next_level.extend(node.values())
                elif isinstance(node, (list, tuple)):
                    next_level.extend(node)
                else:
                    # scalar: nothing to expand
                    continue
            else:
                # Try to treat comp as an integer index if node is list-like
                try_index = None
                if isinstance(node, (list, tuple)):
                    # if comp looks like an integer index
                    try:
                        try_index = int(comp)
                    except Exception:
                        try_index = None

                    if try_index is not None:
                        if -len(node) <= try_index < len(node):
                            next_level.append(node[try_index])
                        # else ignore out-of-range
                    else:
                        # comp is not an index: try to apply comp to each element
                        # (useful when node is list of dicts and comp is a key)
                        for el in node:
                            if isinstance(el, dict) and comp in el:
                                next_level.append(el[comp])
                elif isinstance(node, dict):
                    if comp in node:
                        next_level.append(node[comp])
                else:
                    # scalar node: nothing to extract
                    continue
        current = next_level

    # Flatten current and pick numeric values
    def flatten(items):
        for it in items:
            if isinstance(it, (list, tuple)):
                yield from flatten(it)
            else:
                yield it

    raw_values = list(flatten(current))

    numeric_values: List[float] = []
    for v in raw_values:
        if v is None:
            continue
        if isinstance(v, (int, float)) and not isinstance(v, bool):
            if math.isfinite(v):
                numeric_values.append(float(v))
            continue
        if convert_numbers and isinstance(v, str):
            try:
                f = float(v)
                if math.isfinite(f):
                    numeric_values.append(f)
                continue
            except Exception:
                pass
        # If v is dict/list, try to find numeric nested? skip for simplicity.
        # Only direct scalars are considered numeric.

    if not numeric_values:
        raise ValueError("No numeric values extracted for path: {}".format(path))

    # Plotting
    plt.figure(figsize=figsize)
    if plot_type == 'line':
        plt.plot(range(len(numeric_values)), numeric_values, marker='o')
        plt.xlabel('Index')
        plt.ylabel('Value')
        plt.title(f'Line plot of {len(numeric_values)} values')
    elif plot_type == 'hist':
        plt.hist(numeric_values, bins=bins)
        plt.xlabel('Value')
        plt.ylabel('Frequency')
        plt.title(f'Histogram of {len(numeric_values)} values')
    elif plot_type == 'bar':
        plt.bar(range(len(numeric_values)), numeric_values)
        plt.xlabel('Index')
        plt.ylabel('Value')
        plt.title(f'Bar chart of {len(numeric_values)} values')
    else:
        raise ValueError("Unsupported plot_type: choose 'line', 'hist', or 'bar'")

    plt.tight_layout()
    if save_path:
        plt.savefig(save_path)
    if show:
        plt.show()
    plt.close()

    return numeric_values

# Example usage:
if __name__ == "__main__":
    sample = {
        "items": [
            {"value": "1.2", "name": "a"},
            {"value": 3.4, "name": "b"},
            {"value": "6", "name": "c"}
        ],
        "meta": {"count": 3}
    }
    vals = extract_and_visualize(sample, "items.*.value", plot_type="line")
    print("Extracted:", vals)
```

