Below is a single self-contained Python function that:
- Extracts numeric values from a JSON-like Python structure (dicts/lists) following a specified path of keys.
- Supports wildcard "*" to mean "all keys/elements at this level".
- Returns the list of numeric values and optionally visualizes them with matplotlib (histogram or line plot).
- Uses only the standard library plus matplotlib (the simplest plotting lib).

Copy-paste and run as-is (ensure matplotlib is installed: pip install matplotlib).

```python
import matplotlib.pyplot as plt
from collections.abc import Mapping, Sequence
from typing import Any, List, Union

def extract_and_visualize(json_obj: Any,
                          path: Union[str, List[Union[str,int]]] = "",
                          plot_type: str = "hist",
                          bins: int = 30,
                          title: str = None,
                          show: bool = True,
                          save_path: str = None) -> List[float]:
    """
    Extract numeric values from json_obj following the given path, and visualize them.

    Parameters:
    - json_obj: Python object parsed from JSON (dicts/lists/primitives).
    - path: path to follow. Can be:
       - empty string or empty list -> collect all numeric values in the whole structure
       - dot-separated string like "a.b.*.c"
       - list of segments like ["a","b","*","c"]
       - segments can be '*' (wildcard to traverse all keys/elements) or integer indices for lists.
    - plot_type: "hist" (histogram) or "line" (value vs index). Default "hist".
    - bins: histogram bins (if plot_type == "hist").
    - title: optional plot title.
    - show: whether to call plt.show() (set False to only save).
    - save_path: if given, the plot will be saved to this path (PNG/PDF/etc.).

    Returns:
    - List of numeric values (floats/ints) extracted (bools are excluded).
    """
    # Normalize path to list of segments
    if isinstance(path, str):
        if path == "":
            segments = []
        else:
            segments = [seg for seg in path.split(".") if seg != ""]
    elif isinstance(path, Sequence):
        segments = list(path)
    else:
        raise ValueError("path must be a string or a list/sequence of segments")

    def is_number(x):
        return (isinstance(x, (int, float)) and not isinstance(x, bool))

    results: List[float] = []

    def collect_all_numbers(obj):
        """Recursively collect numeric values from any nested structure."""
        if is_number(obj):
            results.append(obj)
        elif isinstance(obj, Mapping):
            for v in obj.values():
                collect_all_numbers(v)
        elif isinstance(obj, Sequence) and not isinstance(obj, (str, bytes, bytearray)):
            for item in obj:
                collect_all_numbers(item)
        else:
            # non-numeric primitive -> ignore
            pass

    def traverse(obj, seg_index: int):
        """Traverse json_obj following segments starting at seg_index."""
        if seg_index >= len(segments):
            # At end of path: collect all numeric values under this node
            collect_all_numbers(obj)
            return

        seg = segments[seg_index]

        # Wildcard: iterate all keys/elements
        if seg == "*":
            if isinstance(obj, Mapping):
                for v in obj.values():
                    traverse(v, seg_index + 1)
            elif isinstance(obj, Sequence) and not isinstance(obj, (str, bytes, bytearray)):
                for item in obj:
                    traverse(item, seg_index + 1)
            else:
                # can't expand wildcard on non-iterable; nothing to do
                return
        else:
            # Try to access mapping key
            if isinstance(obj, Mapping):
                if seg in obj:
                    traverse(obj[seg], seg_index + 1)
                else:
                    # Missing key: nothing to collect
                    return
            # Try list index (allow string indices convertible to int)
            elif isinstance(obj, Sequence) and not isinstance(obj, (str, bytes, bytearray)):
                # allow integer or string integer
                try:
                    idx = int(seg)
                except Exception:
                    # segment isn't an index; nothing to do
                    return
                if -len(obj) <= idx < len(obj):
                    traverse(obj[idx], seg_index + 1)
                else:
                    return
            else:
                # cannot descend further
                return

    # Start traversal
    if len(segments) == 0:
        collect_all_numbers(json_obj)
    else:
        traverse(json_obj, 0)

    # Convert to floats for plotting consistency
    values = [float(x) for x in results]

    if not values:
        # Nothing to plot; return empty list
        return values

    # Visualization
    plt.figure(figsize=(7, 4.5))
    if title is None:
        title = f"Extracted {len(values)} numeric values"
    if plot_type == "hist":
        plt.hist(values, bins=bins, edgecolor="black")
        plt.xlabel("Value")
        plt.ylabel("Count")
    elif plot_type == "line":
        plt.plot(range(len(values)), values, marker="o", linestyle="-")
        plt.xlabel("Index")
        plt.ylabel("Value")
    else:
        raise ValueError("plot_type must be 'hist' or 'line'")

    plt.title(title)
    plt.tight_layout()

    if save_path:
        plt.savefig(save_path)

    if show:
        plt.show()
    else:
        plt.close()

    return values

# Example usage:
if __name__ == "__main__":
    sample = {
        "a": {"b": [{"c": 1}, {"c": 2}, {"c": 3}], "d": {"c": 10}},
        "x": [100, 200],
        "y": {"z": [{"c": 4.5}, {"c": 5.5}]}
    }
    # Collect all 'c' values under any path a.*.c or y.z.*.c using wildcard:
    vals = extract_and_visualize(sample, path="*.b.*.c", plot_type="hist", bins=5)
    print("Extracted:", vals)
```

Notes and behavior:
- Use "*" to indicate "all keys/elements" at that position.
- If the path ends at a container (dict/list), the function collects all numeric values within that subtree.
- Non-numeric values (strings, booleans) are ignored. Booleans are excluded even though they are ints in Python.
- Returns the list of extracted numbers so you can use them programmatically.

def plot_normalized_series_from_json(json_str, key=None, output_path=None, show=True, vmin=0.0, vmax=1.0):
    """
    Parse a JSON string, extract numerical values, Min-Max normalize them to [vmin, vmax],
    and produce a line plot of the normalized sequence.

    Parameters:
    - json_str (str): JSON document as a string.
    - key (str|None): Optional dot-separated path to a particular field (e.g. "data.values").
                       If None, the function will recursively find all numeric values in the JSON
                       (in traversal order).
                       For lists, you can use numeric indices in the path (e.g. "items.0.value").
    - output_path (str|None): If given, the plot will be saved to this path (PNG, PDF, etc.).
    - show (bool): If True (default), displays the plot with matplotlib.pyplot.show().
    - vmin (float): Target minimum value after normalization (default 0.0).
    - vmax (float): Target maximum value after normalization (default 1.0).

    Returns:
    - tuple(fig, ax, numbers, normalized):
        fig, ax: matplotlib Figure and Axes objects (or (None, None) if plotting failed).
        numbers: list of extracted original numeric values (floats).
        normalized: list of normalized values (floats).

    Raises:
    - ValueError on invalid JSON or if no numeric data is found at the specified location.

    Notes:
    - Boolean values are ignored (since bool is a subclass of int in Python).
    - Strings that can be parsed as floats are accepted as numbers.
    """
    import json
    import math
    import matplotlib.pyplot as plt

    def parse_json(s):
        try:
            return json.loads(s)
        except Exception as e:
            raise ValueError(f"Invalid JSON: {e}")

    def try_float(x):
        # Accept ints/floats (but not bool), and strings that parse to float.
        if isinstance(x, bool):
            return None
        if isinstance(x, (int, float)):
            if math.isfinite(x):
                return float(x)
            return None
        if isinstance(x, str):
            try:
                f = float(x)
                if math.isfinite(f):
                    return f
            except Exception:
                return None
        return None

    def collect_numbers(obj, out):
        # Recursively collect numeric values into out.
        if obj is None:
            return
        v = try_float(obj)
        if v is not None:
            out.append(v)
            return
        if isinstance(obj, dict):
            for val in obj.values():
                collect_numbers(val, out)
            return
        if isinstance(obj, (list, tuple)):
            for el in obj:
                collect_numbers(el, out)
            return
        # other types ignored

    def traverse_path(root, path):
        # path: list of keys; support numeric indices for lists
        cur = root
        for p in path:
            if cur is None:
                return None
            if isinstance(cur, dict):
                # dictionary lookup
                if p in cur:
                    cur = cur[p]
                else:
                    return None
            elif isinstance(cur, (list, tuple)):
                # try to interpret p as an integer index
                try:
                    idx = int(p)
                except Exception:
                    return None
                if 0 <= idx < len(cur):
                    cur = cur[idx]
                else:
                    return None
            else:
                return None
        return cur

    # --- Begin processing ---
    data = parse_json(json_str)

    numbers = []
    if key is None:
        collect_numbers(data, numbers)
    else:
        path = [part for part in key.split('.') if part != ""]
        target = traverse_path(data, path)
        if target is None:
            raise ValueError(f"Key path not found in JSON: {key}")
        # If target is a list/tuple or dict, collect numbers from it; otherwise try to parse as single number
        if isinstance(target, (list, tuple, dict)):
            collect_numbers(target, numbers)
        else:
            v = try_float(target)
            if v is not None:
                numbers.append(v)

    if not numbers:
        raise ValueError("No numeric data found in the JSON (or at the specified key).")

    # Min-Max normalize
    min_x = min(numbers)
    max_x = max(numbers)
    if max_x == min_x:
        # avoid division by zero: map all values to the midpoint of [vmin, vmax]
        mid = (vmin + vmax) / 2.0
        normalized = [mid] * len(numbers)
    else:
        scale = (vmax - vmin) / (max_x - min_x)
        normalized = [((x - min_x) * scale + vmin) for x in numbers]

    # Plot
    try:
        fig, ax = plt.subplots()
        ax.plot(range(len(normalized)), normalized, marker='o', linestyle='-')
        ax.set_xlabel('Index')
        ax.set_ylabel(f'Normalized value [{vmin}, {vmax}]')
        ax.set_title(f'Line plot of Min-Max normalized data (orig min={min_x}, max={max_x})')
        ax.grid(True)
        # Optionally save
        if output_path:
            fig.savefig(output_path, bbox_inches='tight')
        if show:
            plt.show()
        return fig, ax, numbers, normalized
    except Exception as e:
        # plotting failed for some reason; still return data
        return None, None, numbers, normalized

