def analyze_csv_numeric(
    file_path,
    hist_bins=30,
    output_dir=None,
    show_plots=False,
    verbose=True,
):
    """
    Read a CSV file, convert string representations of numbers (including those with commas)
    into floats, compute mean and standard deviation for each numeric column, produce histogram
    plots for each numeric column, and perform a one-way ANOVA across the numeric columns
    (if there are at least two valid groups).

    Dependencies: pandas, numpy, matplotlib, scipy
      pip install pandas numpy matplotlib scipy

    Parameters:
    - file_path: path to CSV file
    - hist_bins: number of bins for histograms (default 30)
    - output_dir: directory to save histogram PNG files (default './histograms')
    - show_plots: if True, display plots interactively (default False)
    - verbose: if True, print a brief summary (default True)

    Returns:
    A dictionary with keys:
      - 'summary': dict mapping column -> {'mean': ..., 'std': ..., 'count': ...}
      - 'histograms': dict mapping column -> path_to_png
      - 'anova': dict with keys 'F', 'p', 'groups' (list of group sizes), or None if ANOVA not applicable
    """
    import os
    import re
    import math
    from pathlib import Path

    import pandas as pd
    import numpy as np
    import matplotlib.pyplot as plt
    from scipy import stats

    # Helper to safely parse numeric-like strings (handles commas as thousands sep or decimal sep)
    def parse_number_string(s):
        # Return np.nan for null/empty
        if s is None:
            return np.nan
        if isinstance(s, (int, float, np.floating, np.integer)):
            return float(s)
        s = str(s).strip()
        if s == "":
            return np.nan
        # Remove currency symbols and spaces
        s = s.replace('\xa0', '')  # non-breaking space
        s = re.sub(r'[^\d\-\+\.,\(\)eE]', '', s)  # keep digits, signs, comma, dot, parentheses, exponent
        if s == "":
            return np.nan
        # Handle parentheses for negatives: (123) -> -123
        if s.startswith('(') and s.endswith(')'):
            s_inner = s[1:-1]
            val = parse_number_string(s_inner)
            return -val if not math.isnan(val) else np.nan

        # If scientific notation present, try direct float after normalizing commas
        if re.search(r'[eE]', s):
            # remove thousand separators (commas or dots) if present before exponent
            # Replace comma thousand separators simply by removing commas
            s_clean = s.replace(',', '')
            try:
                return float(s_clean)
            except Exception:
                pass

        # Count dot/comma occurrences
        dot_count = s.count('.')
        comma_count = s.count(',')

        # Case: both present -> decide based on last occurrence
        if dot_count > 0 and comma_count > 0:
            if s.rfind(',') > s.rfind('.'):
                # comma likely decimal sep, dots are thousands: remove dots, replace comma->dot
                s2 = s.replace('.', '').replace(',', '.')
            else:
                # dot likely decimal sep, remove commas
                s2 = s.replace(',', '')
            try:
                return float(s2)
            except Exception:
                return np.nan

        # Case: only commas present
        if comma_count > 0 and dot_count == 0:
            parts = s.split(',')
            # If exactly one comma and the part after comma is not length 3, treat comma as decimal sep
            if comma_count == 1 and len(parts[-1]) != 3:
                s2 = s.replace(',', '.')
            else:
                # treat commas as thousands separators
                s2 = s.replace(',', '')
            try:
                return float(s2)
            except Exception:
                return np.nan

        # Case: only dots present or neither
        try:
            return float(s)
        except Exception:
            return np.nan

    # Ensure file exists
    fp = Path(file_path)
    if not fp.exists():
        raise FileNotFoundError(f"CSV file not found: {file_path}")

    # Read CSV with pandas
    try:
        df = pd.read_csv(fp, dtype=str)  # read everything as string initially to allow cleaning
    except Exception as e:
        # try with default separator sniffing fallback
        df = pd.read_csv(fp, sep=None, engine='python', dtype=str)

    if df.shape[1] == 0:
        raise ValueError("No columns found in CSV.")

    # Trim whitespace from column names
    df.columns = [str(c).strip() for c in df.columns]

    # Parse each column attempting numeric conversion
    parsed = {}
    for col in df.columns:
        col_series = df[col].astype(object).map(lambda x: parse_number_string(x))
        # Convert to numeric numpy array with NaNs
        parsed[col] = pd.to_numeric(col_series, errors='coerce')

    parsed_df = pd.DataFrame(parsed)

    # Identify numeric columns: those with at least one non-NaN value and numeric dtype
    numeric_cols = [c for c in parsed_df.columns if parsed_df[c].dropna().shape[0] > 0]

    if len(numeric_cols) == 0:
        raise ValueError("No numeric columns detected after parsing.")

    # Prepare output dir
    if output_dir is None:
        output_dir = Path.cwd() / "histograms"
    else:
        output_dir = Path(output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)

    summary = {}
    hist_paths = {}

    for col in numeric_cols:
        series = parsed_df[col].dropna().astype(float)
        count = int(series.size)
        if count == 0:
            mean = float('nan')
            std = float('nan')
        else:
            mean = float(series.mean())
            std = float(series.std(ddof=1)) if count > 1 else float('nan')
        summary[col] = {"mean": mean, "std": std, "count": count}

        # Plot histogram
        if count > 0:
            plt.figure()
            plt.hist(series, bins=hist_bins, color='C0', edgecolor='black')
            plt.xlabel(col)
            plt.ylabel("Frequency")
            plt.title(f"Histogram of {col} (n={count})")
            safe_name = re.sub(r'[^\w\-_\. ]', '_', col)[:200]
            out_path = output_dir / f"hist_{safe_name}.png"
            plt.tight_layout()
            plt.savefig(out_path)
            if show_plots:
                plt.show()
            plt.close()
            hist_paths[col] = str(out_path)
        else:
            hist_paths[col] = None

    # Perform one-way ANOVA if applicable: need at least two groups with >=2 observations each
    anova_result = None
    groups_for_anova = []
    group_sizes = []
    for col in numeric_cols:
        grp = parsed_df[col].dropna().astype(float).values
        if grp.size >= 2:
            groups_for_anova.append(grp)
            group_sizes.append(int(grp.size))

    if len(groups_for_anova) >= 2:
        # scipy.stats.f_oneway will raise if any group has zero variance? It still returns F, p (but check)
        try:
            F_stat, p_val = stats.f_oneway(*groups_for_anova)
            anova_result = {"F": float(F_stat), "p": float(p_val), "groups": group_sizes}
        except Exception as e:
            anova_result = {"error": str(e)}
    else:
        anova_result = None

    result = {"summary": summary, "histograms": hist_paths, "anova": anova_result}

    if verbose:
        print("Numeric columns detected:", numeric_cols)
        print("Summary (mean, std, count) per column:")
        for col, statsd in summary.items():
            print(f" - {col}: mean={statsd['mean']}, std={statsd['std']}, n={statsd['count']}")
        print(f"Histogram files saved to: {output_dir}")
        if anova_result is None:
            print("ANOVA not performed (need at least two groups with >=2 observations each).")
        elif "error" in anova_result:
            print("ANOVA error:", anova_result["error"])
        else:
            print(f"ANOVA one-way F={anova_result['F']}, p={anova_result['p']}, group_sizes={anova_result['groups']}")

    return result

