import json
import re
from ast import literal_eval

def fetch_scripts_as_dicts(url, timeout=10):
    """
    Fetch a webpage, extract all <script> tag contents, and attempt to evaluate
    object-like strings found inside those scripts as Python dictionaries.
    Returns a list of dictionaries successfully parsed (may be empty).

    Uses only Python's standard library.
    """
    # --- HTML script extractor ---
    class ScriptExtractor(HTMLParser):
        def __init__(self):
            super().__init__()
            self.in_script = False
            self.current = []
            self.scripts = []

        def handle_starttag(self, tag, attrs):
            if tag.lower() == "script":
                self.in_script = True
                self.current = []

        def handle_endtag(self, tag):
            if tag.lower() == "script" and self.in_script:
                self.in_script = False
                self.scripts.append("".join(self.current))

        def handle_data(self, data):
            if self.in_script:
                self.current.append(data)

    # --- helper: extract balanced {...} substrings ignoring braces in quotes ---
    def find_braced_objects(text):
        results = []
        i = 0
        n = len(text)
        while i < n:
            if text[i] == '{':
                start = i
                i += 1
                depth = 1
                in_quote = None
                escaped = False
                while i < n and depth > 0:
                    ch = text[i]
                    if escaped:
                        escaped = False
                    elif ch == '\\':
                        escaped = True
                    elif in_quote:
                        if ch == in_quote:
                            in_quote = None
                    elif ch == '"' or ch == "'":
                        in_quote = ch
                    elif ch == '{':
                        depth += 1
                    elif ch == '}':
                        depth -= 1
                    i += 1
                if depth == 0:
                    results.append(text[start:i])
                else:
                    # unbalanced, discard
                    break
            else:
                i += 1
        return results

    # --- helper: try parsing one candidate string to a dict ---
    def try_parse_candidate(s):
        s_strip = s.strip()
        # try json first (common for application/ld+json or JSON blobs)
        try:
            obj = json.loads(s_strip)
            if isinstance(obj, dict):
                return obj
        except Exception:
            pass
        # try python literal eval (accepts single quotes)
        try:
            obj = literal_eval(s_strip)
            if isinstance(obj, dict):
                return obj
        except Exception:
            pass
        # Heuristic: quote unquoted keys (very simple, won't handle every JS expression)
        # Replace occurrences like: { key:  or , key:  with "key":
        def quote_keys(js_text):
            # This regex aims to match unquoted identifiers used as object keys.
            pattern = re.compile(r'([{\s,])([A-Za-z_][A-Za-z0-9_-]*)(\s*):')
            prev = None
            cur = js_text
            # apply repeatedly to catch nested cases
            for _ in range(5):
                new = pattern.sub(r'\1"\2"\3:', cur)
                if new == cur:
                    break
                cur = new
            return cur

        try:
            fixed = quote_keys(s_strip)
            obj = json.loads(fixed)
            if isinstance(obj, dict):
                return obj
        except Exception:
            pass

        # last attempt: try literal_eval on the quoted-keys version (Python dict style)
        try:
            obj = literal_eval(fixed)
            if isinstance(obj, dict):
                return obj
        except Exception:
            pass

        return None

    # --- fetch page ---
    try:
        with urllib.request.urlopen(url, timeout=timeout) as resp:
            raw = resp.read()
            # try to decode using charset if provided
            charset = None
            info = resp.headers.get('Content-Type')
            if info:
                m = re.search(r'charset=([^\s;]+)', info, flags=re.I)
                if m:
                    charset = m.group(1).strip('"').strip("'")
            if charset:
                try:
                    text = raw.decode(charset, errors="replace")
                except Exception:
                    text = raw.decode('utf-8', errors="replace")
            else:
                try:
                    text = raw.decode('utf-8')
                except Exception:
                    text = raw.decode('latin-1', errors="replace")
    except urllib.error.URLError as e:
        raise RuntimeError(f"Failed to fetch URL {url!r}: {e}") from e

    # --- parse scripts ---
    parser = ScriptExtractor()
    parser.feed(text)
    scripts = parser.scripts

    parsed_dicts = []
    for script_text in scripts:
        if not script_text or not script_text.strip():
            continue
        # If the whole script looks like JSON/object, try it directly first
        obj = try_parse_candidate(script_text)
        if obj is not None:
            parsed_dicts.append(obj)
            continue
        # Otherwise, look for object-like substrings { ... } and try them
        candidates = find_braced_objects(script_text)
        for c in candidates:
            obj = try_parse_candidate(c)
            if obj is not None:
                parsed_dicts.append(obj)
                # do not break; allow finding multiple dicts per script
    return parsed_dicts

