                depth = 0
                in_single = False
                in_double = False
                in_backtick = False
                escape = False
                j = i
                while j < n:
                    c = text[j]
                    if escape:
                        escape = False
                    elif c == "\\":
                        escape = True
                    elif in_single:
                        if c == "'" and not escape:
                            in_single = False
                    elif in_double:
                        if c == '"' and not escape:
                            in_double = False
                    elif in_backtick:
                        if c == "`" and not escape:
                            in_backtick = False
                    else:
                        if c == "'":
                            in_single = True
                        elif c == '"':
                            in_double = True
                        elif c == "`":
                            in_backtick = True
                        elif c == "{":
                            depth += 1
                        elif c == "}":
                            depth -= 1
                            if depth == 0:
