        except Exception:
            pass
        # Try replacing JS tokens true/false/null -> Python equivalents outside strings
        mapping = {"true": "True", "false": "False", "null": "None"}
        transformed = replace_tokens_outside_quotes(s_stripped, mapping)
        try:
            obj = ast.literal_eval(transformed)
            if isinstance(obj, dict):
                return obj
        except Exception:
            pass
        # As a last try, try json.loads on transformed but ensure double quotes for JSON keys/strings:
        # (Only a best-effort; we will not attempt complex JS->JSON conversions.)
        try:
            obj = json.loads(transformed)
            if isinstance(obj, dict):
                return obj
        except Exception:
            pass
        return None

    # --- Fetch page ---
    try:
        with urllib.request.urlopen(url, timeout=timeout) as resp:
            # try to get encoding from headers, fallback to utf-8
            content_type = resp.headers.get("Content-Type", "")
            charset = "utf-8"
            if "charset=" in content_type:
                try:
                    charset = content_type.split("charset=")[1].split(";")[0].strip()
                except Exception:
                    charset = "utf-8"
            raw = resp.read()
            try:
                html = raw.decode(charset, errors="replace")
            except Exception:
                html = raw.decode("utf-8", errors="replace")
    except urllib.error.URLError as e:
        raise RuntimeError(f"Failed to fetch URL {url}: {e}") from e

    # --- Parse scripts ---
    extractor = ScriptExtractor()
    extractor.feed(html)

    parsed_dicts = []
    for script_text in extractor.scripts:
        # find object-like chunks
        for chunk in extract_brace_objects(script_text):
            parsed = try_parse_object(chunk)
            if isinstance(parsed, dict):
                parsed_dicts.append(parsed)

    return parsed_dicts
```

